// Catergory indices (whites, blacks, blues, etc)
let cind = [0,8,16,23,34,45,61,75,81,99,110], 
// color names from Werner's Nomenclature of Colors
cnames = ["Snow White","Reddish White","Purplish White","Yellowish White","Orange-Coloured White","Greenish White","Skimmed-Milk White","Greyish White","Ash Grey","Smoke Grey","French Grey","Pearl Grey","Yellowish Grey","Bluish Grey","Greenish Grey","Blackish Grey","Greyish Black","Bluish Black","Greenish Black","Pitch, or Brownish Black","Reddish Black","Ink Black","Velvet Black","Scotch Blue","Prussian Blue","Indigo Blue","China Blue","Azure Blue","Ultramarine Blue","Flax-Flower Blue","Berlin Blue","Verditter Blue","Greenish Blue","Greyish Blue","Bluish Lilac Purple","Bluish Purple","Violet Purple","Pansy Purple","Campanula Purple","Imperial Purple","Auricula Purple","Plum Purple","Red Lilac Purple","Lavender Purple","Pale Blackish Purple","Celadine Green","Mountain Green","Leek Green","Blackish Green","Verdigris Green","Bluish Green","Apple Green","Emerald Green","Grass Green","Duck Green","Sap Green","Pistachio Green","Asparagus Green","Olive Green","Oil Green","Siskin Green","Sulphur Yellow","Primrose Yellow","Wax Yellow","Lemon Yellow","Gamboge Yellow","King's Yellow","Saffron Yellow","Gallstone Yellow","Honey Yellow","Straw Yellow","Wine Yellow","Sienna Yellow","Ochre Yellow","Cream Yellow","Dutch Orange","Buff Orange","Orpiment Orange","Brownish Orange","Reddish Orange","Deep Reddish Orange","Tile Red","Hyacinth Red","Scarlet Red","Vermilion Red","Aurora Red","Arterial Blood Red","Flesh Red","Rose Red","Peach Blossom Red","Carmine Red","Lake Red","Crimson Red","Purplish Red","Cochineal Red","Veinous Blood Red","Brownish Purple Red","Chocolate Red","Brownish Red","Deep Orange-Coloured Brown","Deep Reddish Brown","Umber Brown","Chestnut Brown","Yellowish Brown","Wood Brown","Liver Brown","Hair Brown","Broccoli Brown","Olive Brown","Blackish Brown"];

let pals=[];
R=(a=1)=>Math.random()*a; 
RT=(a=1)=>a*(R()-R());
C=(a)=>R()<a;

function getColors(){
    Nc = 2 + (R(8)|0); //number of colors
    pals.length = 0;
    let cat=[0,0,0,0,0,0,0,0,0];
    let cpick=R()<.1;
    let palsh=[];
    for (let i=0;i<Nc;i++){
        if (cpick){
            palsh[i] = ~~(R(110));
        } else {
            let flag=1;
            let ncat
            while(flag){
                ncat = ~~(R(cat.length));
                if (cat[ncat]==0){
                    flag=0;
                    cat[ncat]=1;
                }
            }
            palsh[i]=cind[ncat]+~~R(cind[ncat+1]-cind[ncat]);
        }
    }
    pals = [...new Set(palsh)]; //remove duplicates
    Nc = pals.length;
}

let w,h;
function setup(){
    getColors();
    w = windowWidth;
    h = windowHeight;
    createCanvas(w,h)
    colorMode(HSL);
    // noLoop() removed for animation
    noStroke();
    textAlign(CENTER,CENTER);
}

function draw(){
    let dx = w/Nc;
    for (let i=0;i<Nc;i++){
        let col = ncols[pals[i]] 
        fill(col)
        rect(i*dx,0,dx+1,h)
        fill(col[2]<50?100:0)
        textSize(dx/7)
        let hexcode = hslToHex(...col);
        text(hexcode,i*dx+dx/2,h-3*dx/10)
        textSize(dx*.07)
        text(cnames[pals[i]]+' (#'+pals[i]+')',i*dx+dx/2,h-1.5*dx/10)
    }
    loadPixels();
    for (let p=0; p<pixels.length; p+=4){
      dp=RT(7);
      pixels[p]=pixels[p]+dp;
      pixels[p+1]=pixels[p+1]+dp;
      pixels[p+2]=pixels[p+2]+dp;
    }
    updatePixels();
}

function  keyPressed(){
    if (keyCode==32){
        w = windowWidth;
        h = windowHeight;
        getColors();
        resizeCanvas(w,h);
        redraw();

    }
    if (keyCode==83){
        let colNums='';
        let colNames='Color Names: ';
        let hexCodes='Hex Values: ';
        let hslVals='HSL values: ';
        for (let i=0;i<Nc;i++){
            colNums+=pals[i]
            if (i<Nc-1)colNums+='_'
            colNames+=pals[i]+' '+cnames[pals[i]];
            if (i<Nc-1)colNames+=', '
            hexCodes+='#'+hslToHex(...ncols[pals[i]]);
            if (i<Nc-1)hexCodes+=', '
            hslVals+='['+ncols[pals[i]]+']';
            if (i<Nc-1)hslVals+=','
        }
        save('Palette_n'+Nc+'_'+colNums)
        download('Palette_n'+Nc+'_'+colNums,colNames+'\n'+hexCodes+'\n'+hslVals)
    }
}

function hslToHex(h, s, l) {
    l /= 100;
    const a = s * Math.min(l, 1 - l) / 100;
    const f = n => {
        const k = (n + h / 30) % 12;
        const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
        return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `${f(0)}${f(8)}${f(4)}`;
}

function download(filename, text) {
    var pom = document.createElement('a');
    pom.setAttribute('href', 'data:text/plain;charset=utf-8,' + encodeURIComponent(text));
    pom.setAttribute('download', filename);
    if (document.createEvent) {
        var event = document.createEvent('MouseEvents');
        event.initEvent('click', true, true);
        pom.dispatchEvent(event);
    }
    else {
        pom.click();
    }
  }
